// Docker incarnation: a restart gets a new mutex namespace. Old empty locks are not stolen.
const RUNTIME=(()=>{const f=require('fs');try{
 const boot=f.readFileSync('/proc/sys/kernel/random/boot_id','utf8').trim();
 const stat=f.readFileSync('/proc/1/stat','utf8');const fields=stat.slice(stat.lastIndexOf(')')+2).split(' ');
 if(!/^[a-f0-9-]{36}$/.test(boot)||!/^\d+$/.test(fields[19]))throw Error();return boot+'-'+fields[19];
}catch(_){throw new Error('Recovery requires the configured Linux Docker container (/proc readable).');}})();

// Shared, embedded in Code nodes. Requires only built-in fs and shared /files.
const S = (() => {
  const fs=require('fs');
  const root='/files/.telegram-ui/scheduler', jobs=root+'/jobs', control=root+'/control.json';
  fs.mkdirSync(jobs,{recursive:true,mode:0o700});
  const execution=String($execution.id);
  const valid=id=>typeof id==='string'&&/^[A-Za-z0-9_-]{1,80}$/.test(id);
  const jobPath=id=>{if(!valid(id))throw new Error('Invalid request_id');return jobs+'/'+id+'.json';};
  const read=(p,fallback)=>fs.existsSync(p)?JSON.parse(fs.readFileSync(p,'utf8')):fallback;
  function write(p,value){
    const temp=p+'.tmp-'+execution+'-'+Date.now();let fd;
    try{fd=fs.openSync(temp,'wx',0o600);fs.writeFileSync(fd,JSON.stringify(value));fs.fsyncSync(fd);fs.closeSync(fd);fd=undefined;fs.renameSync(temp,p);}
    finally{if(fd!==undefined)fs.closeSync(fd);if(fs.existsSync(temp))fs.unlinkSync(temp);}
  }
  function tx(fn){
    let fd;try{fd=fs.openSync(control+'.lock-'+RUNTIME,'wx',0o600);}catch(e){if(e.code==='EEXIST')return {mutex_busy:true};throw e;}
    try{const c=read(control,{version:1,lease:null,generation_waiters:[],postprocess_waiters:[]});c.generation_waiters??=[];c.postprocess_waiters??=[];const result=fn(c);write(control,c);return result;}
    finally{fs.closeSync(fd);fs.unlinkSync(control+'.lock-'+RUNTIME);}
  }
  const get=id=>read(jobPath(id),null);
  const patch=(id,data)=>{const j=get(id);if(!j)throw new Error('Missing job '+id);const index=read(root+'/executions/'+execution+'.json',null);if(index?.request_id===id&&j.execution_id!==execution)throw new Error('Obsolete worker fenced by recovery.');if(j.cancel_requested&&execution===j.execution_id&&data.status&&data.status!=='deleted')data={...data,status:j.status};Object.assign(j,data,{updated_at:new Date().toISOString()});write(jobPath(id),j);return j;};
  function owned(c,kind){if(c.lease?.owner!==execution||c.lease?.kind!==kind||c.lease.blocked)throw new Error('Comfy reservation is absent or blocked; inspect scheduler before resubmitting.');}
  return {fs,root,jobs,execution,valid,jobPath,read,write,tx,get,patch,owned,control};
})();



const setting=$('Recovery Settings').first().json;
const q=$input.first().json;
if(setting.confirm_original_execution_stopped!==true||!/^\d+$/.test(setting.owner_execution_id))throw new Error('Inspect and stop the original n8n execution, then enter its ID and set confirmation=true in Recovery Settings.');
if(!Array.isArray(q.queue_running)||!Array.isArray(q.queue_pending)||q.queue_running.length||q.queue_pending.length)throw new Error('Comfy must have no running or pending tasks before recovery.');
const owner=setting.owner_execution_id;
const result=S.tx(c=>{
 if(c.stop_pending||c.recovery_active)throw new Error('Use the bot to finish the active stop/recovery before any manual release.');
  const own=c.lease?.owner===owner;
  const waiting=c.postprocess_waiters.some(w=>w.owner===owner)||c.generation_waiters.some(w=>w.owner===owner);
  const index=S.read(S.root+'/executions/'+owner+'.json',null);
  if(!own&&!waiting&&!index?.request_id)throw new Error('This execution has no known reservation, waiter or job record. Nothing changed.');
  const id=own?c.lease.request_id:waiting?[...c.postprocess_waiters,...c.generation_waiters].find(w=>w.owner===owner).request_id:index.request_id;
  const selected=S.get(id);
  if(selected&&String(selected.execution_id)!==owner)throw new Error('This execution was replaced. Refusing to cancel the current worker.');
  if(selected?.inflight)throw new Error('An in-flight submission requires authenticated /stop or recovery, not a manual lease release.');
  const directory='/files/.telegram-ui/submissions',boot=S.read('/files/.telegram-ui/comfy-boot.json',null);
  if(S.fs.existsSync(directory))for(const file of S.fs.readdirSync(directory).filter(n=>n.startsWith(id+'-')&&n.endsWith('.json'))){const receipt=S.read(directory+'/'+file,null);if(receipt?.boot_id===boot?.boot_id&&receipt.intent&&!receipt.response?.prompt_id)throw new Error('Unconfirmed HTTP submission. Restart Comfy and finish /stop instead of releasing this lease manually.');}
  if(own){c.lease=null;c.paused=false;}
  c.postprocess_waiters=c.postprocess_waiters.filter(w=>w.owner!==owner);
  c.generation_waiters=c.generation_waiters.filter(w=>w.owner!==owner);
  const job=S.get(id);
  if(job&&job.status!=='finished')S.patch(id,{inflight:null,cancel_requested:true,status:job.status==='failed'?'failed':'cancelled',recovery_note:'Original execution stopped and reservation manually released. No Comfy task was resubmitted.'});
  return {recovered:true,request_id:id,owner_execution_id:owner,message:"Reservation released. No task was resubmitted."};
});
if(result.mutex_busy)throw new Error('Scheduler busy; retry this recovery after it is idle. Nothing changed.');
return [{json:result}];
